import json, base64, importlib
import samples as S; importlib.reload(S)
INS = {
 1:("bass.fat",64,128), 2:("lead.saw",56,128), 3:("arp.pluck",58,152),
 4:("pad.soft",44,118), 5:("dr.kick",64,128), 6:("dr.snare",62,140),
 7:("dr.hat",48,172), 8:("dr.ohat",40,96), 9:("dr.clap",46,140),
 10:("dr.tom",56,108), 11:("fx.sweep",44,128), 12:("lead.square",52,128),
}
LOOPS={2:S.lead,4:S.pad,12:S.lead_sq}
ONES={1:S.bass,3:S.pluck,5:S.kick,6:S.snare,7:S.hat,8:S.openhat,9:S.clap,10:S.tom,11:S.sweep}
calls=[]
for ins,(nm,vol,pan) in INS.items():
    if ins in LOOPS:
        pcm,ls,ll=LOOPS[ins](); flags=17
    else:
        pcm=ONES[ins](); ls=ll=None; flags=16
    calls.append({"name":"sample_create_from_pcm","arguments":{"instrument":ins,"sample":0,"pcm":S.b64(pcm),"encoding":"int16","name":nm}})
    args={"instrument":ins,"sample":0,"volume":vol,"panning":pan,"flags":flags,"name":nm}
    if ls is not None: args["loop_start"]=ls; args["loop_length"]=ll
    calls.append({"name":"sample_set","arguments":args})
    calls.append({"name":"instrument_set","arguments":{"instrument":ins,"name":nm}})
json.dump(calls,open("batch_instr.json","w"))
print("ok",len(calls))
EOF
